'use strict';
const http=require('node:http'),fs=require('node:fs'),path=require('node:path');
const html=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SisVentas · preparación local</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0a1220;color:#e6edf8;font:15px system-ui}header{padding:20px 6%;background:#101c2e;border-bottom:1px solid #2b3c55}main{max-width:1000px;margin:36px auto;padding:0 20px}small,p{color:#a9b9cf}.panel{border:1px solid #30425c;border-radius:18px;background:#121f32;padding:24px;margin:20px 0}.row{display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap}button,select{font:inherit;border-radius:9px;padding:12px 16px;border:1px solid #405676;background:#1c304d;color:inherit}button{cursor:pointer;background:#e6efff;color:#14243b}button:disabled{opacity:.7;cursor:default}button:focus-visible,select:focus-visible{outline:3px solid #87b5ff;outline-offset:3px}h1{font-size:25px}strong{color:#8bdb98}#status{min-height:30px;margin:22px 0}.spin{display:inline-block;border:2px solid #839bbd;border-top-color:transparent;border-radius:50%;width:15px;height:15px;vertical-align:middle;margin-right:8px;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.values{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.values b{display:block;font-size:21px;margin-top:8px}@media(max-width:500px){.panel{padding:18px}.values{grid-template-columns:1fr}select,button{width:100%}}</style>
<header>SisVentas <small> · Vista local con datos ficticios</small></header><main><h1>Preparación de ventas y presupuestos</h1><p>El documento ya tiene responsable. Se consulta su ficha directamente; la preparación no guarda importes ni movimientos.</p>
<section class="panel"><div class="row"><div><small>PP-DEMO · Cliente de ejemplo</small><h2>Presupuesto aprobado</h2></div><select id="mode" aria-label="Caso de prueba"><option value="normal">Cuenta habilitada</option><option value="denied">Permiso revocado</option><option value="legacy">Documento histórico sin vínculo</option></select></div><div class="values"><div><small>Total</small><b>$ 121.000</b></div><div><small>Costo conservado</small><b>$ 55.000</b></div><div><small>Cobros existentes</small><b>$ 20.000</b></div></div><div id="status" role="status">Listo para probar.</div><button id="prepare">Preparar documento</button></section>
<section class="panel"><div class="row"><span>Lecturas de la ficha <strong id="reads">0</strong></span><span>Solicitudes a Cotizador <strong id="api">0</strong></span><span>Escrituras <strong>0</strong></span></div><p>Conteos del ensayo ficticio, no una medición de facturación. El guardado financiero posterior conserva sus controles.</p></section></main>
<script>
window.currentUserUid='demo';window.currentRole='administrativo';window.PERMISOS_ROLES={administrativo:{indiceRevision:1}};window.fbAuth={currentUser:{uid:'demo',getIdToken:async()=> 'fictitious'}};window.fbDB={};window.fbRef=(_,p)=>p;
const record={id:'PP-DEMO',responsableUid:'demo',total:121000,pagado:20000,items:[{cod:'DEMO',qty:1,punit:100000,costoUnitarioCompra:55000}]};window.pptoData=[{...record,fbKey:'demo'}];let reads=0,api=0;
window.fbGet=async()=>{reads++;document.getElementById('reads').textContent=reads;await new Promise(r=>setTimeout(r,150));if(document.getElementById('mode').value==='denied')throw Error('No tenés permiso para consultar este documento.');return{val:()=>structuredClone(record)}};
window.SISVENTAS_FUNCTIONS={cotizadorProveedor:'/fixture-only'};window.fetch=async()=>{api++;document.getElementById('api').textContent=api;return{ok:true,status:200,json:async()=>({ok:true,record:structuredClone(record)})}};
</script><script src="/commercial-ownership.js"></script><script>
document.getElementById('prepare').onclick=async function(){this.disabled=true;this.innerHTML='<span class="spin" aria-hidden="true"></span>Preparando…';reads=api=0;document.getElementById('reads').textContent='0';document.getElementById('api').textContent='0';const status=document.getElementById('status');status.textContent='Consultando el documento…';window.pptoData=[{...record,fbKey:'demo'}];if(document.getElementById('mode').value==='legacy')delete window.pptoData[0].responsableUid;try{const result=await SVCommercialOwnership.prepare('presupuestos','demo');if(result.record.total!==121000||result.record.items[0].costoUnitarioCompra!==55000)throw Error('Valores alterados');status.textContent='Documento listo. Importes, cobros y comisionado conservados.';}catch(e){status.textContent=e.message;}finally{this.disabled=false;this.textContent='Preparar documento';}};
</script></html>`;
async function start(port=0){const source=fs.readFileSync(path.resolve(__dirname,'../../js/core/commercial-ownership.js'));const server=http.createServer((req,res)=>{if(req.url!=='/'&&req.url!=='/commercial-ownership.js'){res.writeHead(404);return res.end();}res.writeHead(200,{'Content-Type':req.url==='/'?'text/html; charset=utf-8':'application/javascript','Cache-Control':'no-store','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'none'; img-src 'none'; object-src 'none'; frame-src 'none'"});res.end(req.url==='/'?html:source);});await new Promise(r=>server.listen(port,'127.0.0.1',r));return{server,url:'http://127.0.0.1:'+server.address().port+'/'};}
module.exports={start};if(require.main===module)start(Number(process.argv[2]||8896)).then(x=>process.stdout.write(x.url+'\n'));
